export const getCreateSkillUrl = () => {




  return `/api/skills`
}

/**
 * @summary Create a new skill
 */
export const createSkill = async (skillInput: SkillInput, options?: RequestInit): Promise<Skill> => {

  return customFetch<Skill>(getCreateSkillUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(
      skillInput,)
  }
);}




export const getCreateSkillMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createSkill>>, TError,{data: BodyType<SkillInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof createSkill>>, TError,{data: BodyType<SkillInput>}, TContext> => {

const mutationKey = ['createSkill'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof createSkill>>, {data: BodyType<SkillInput>}> = (props) => {
          const {data} = props ?? {};

          return  createSkill(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type CreateSkillMutationResult = NonNullable<Awaited<ReturnType<typeof createSkill>>>
    export type CreateSkillMutationBody = BodyType<SkillInput>
    export type CreateSkillMutationError = ErrorType<unknown>

    /**
 * @summary Create a new skill
 */
export const useCreateSkill = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createSkill>>, TError,{data: BodyType<SkillInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof createSkill>>,
        TError,
        {data: BodyType<SkillInput>},
        TContext
      > => {
      return useMutation(getCreateSkillMutationOptions(options));
    }

